<template>
	<div class="flex h-screen items-center justify-center bg-gray-100">
		<div class="absolute top-4 left-4">
			<BrandLogo />
		</div>
		<LanguageSelector
			:selectedLanguage="selectedLanguage"
			@change-language="changeLanguage"
		/>

		<!-- Centered Box -->
		<div class="relative flex flex-col items-center justify-center space-y-6 p-10 bg-white rounded-xl shadow-xl border border-gray-300 w-auto max-w-[40vw] h-auto max-h-[40vh]">
			<!-- Success Icon/Image -->
			<div class="absolute top-4 left-4">
				<Breadcrumbs :items="[
					{
						label: 'Home',
						route: {
							name: 'Home',
						},
					},
					{
						label: 'Book Appointment',
						route: '/Appointment',
					},
					{
						label: 'Payment',
						route: '/Payment?practitioner='+practitioner+'='+appointment,
					},
				]"
				/>
			</div>
			<FeatherIcon :name="'credit-card'"
				class="h-14 w-14 object-contain" />

			<div>
				<table class="text w-[23vw]">
					<tbody>
						<tr>
							<td>
								<p class="text-left">
									Consultation Amount:
								</p>
							</td>
							<td><p class="font-bold text-right">
									₹ {{ consultation_charge }}/-
								</p>
							</td>
						</tr>
						<tr v-if=registration_fee>
							<td>
								<p class="text-left">
									Registration Fee:
								</p>
							</td>
							<td >
								<p class="font-bold text-right">
									₹ {{ registration_fee }}/-
								</p>
							</td>
						</tr>
						<tr>
							<td>
								<br>
								<p class="font-bold text-center">
									Total:
								</p>
							</td>
							<td>
								<br>
								<p class="text-1xl font-bold text-[red] text-right">
									₹ {{ total_amount }}/-
								</p>
							</td>
						</tr>
					</tbody>
				</table>
			</div>
			<!-- Action Buttons -->
			<div class="flex space-x-4">
				<Button
					size="lg"
					:class="'px-6 py-2 bg-gray-300 text-gray-700 font-semibold rounded-lg !bg-[#b3bf79] focus:ring-2 focus:ring-[#b3bf79] focus:outline-none transition-all'"
					:loading="createRazorpayOrder.loading"
					@click="createRazorpayOrder.submit()"
				>
					{{ translations[selectedLanguage].payNow }}
				</Button>
				<button
					class="px-6 py-2 bg-gray-300 text-gray-700 font-semibold rounded-lg focus:ring-2 focus:ring-gray-300 transition-all"
					@click="goToHome"
				>
					{{ translations[selectedLanguage].leave }}
				</button>
			</div>
			<ErrorMessage class="mt-3" :message="createRazorpayOrder.error" />
		</div>
		<Footer />
	</div>
</template>


<script setup>
	import { useRouter, useRoute } from "vue-router";
	import { Button, createResource, ErrorMessage, Breadcrumbs } from "frappe-ui"
	import { ref, onMounted, onBeforeUnmount, } from "vue";
	import LanguageSelector from '@/components/LanguageSelector.vue';
	import Footer from '@/components/Footer.vue';
	import BrandLogo from '@/components/BrandLogo.vue';

	const emit = defineEmits(["success"])

	const router = useRouter();
	const route = useRoute();
	const practitioner = route.query.practitioner;
	const appointment = route.query.appointment;
	let from_checkin = route.query.from_checkin || null;
	let consultation_charge = ref(0);
	let registration_fee = ref(0);
	let total_amount = ref(0);
	let has_registration_fee = ref(false);
	let logo = ref("");
	let get_logo = createResource({
		url:"/api/method/marley_frontend.api.get_logo_image",
		method: "GET",
		makeParams() {
			return {};
		},
		onSuccess(response) {
			if (response) {
				logo.value = response;
			}
			else {
				logo.value = "https://raw.githubusercontent.com/frappe/healthcare/develop/healthcare/public/images/healthcare.svg";
			}
		},
	})
	get_logo.fetch()

	// Define translations
	const translations = {
		en: {
			payNow: "Pay Now",
			leave: "I'm Done!",
		},
		ar: {
			payNow: "دفع الآن",
			leave: "مغادرة",
		},
		ml: {
			payNow: "ഇപ്പോൾ അടയ്ക്കുക",
			leave: "തിരിച്ച് പോവുക",
		},
	};
	const selectedLanguage = ref(localStorage.getItem("selectedLanguage") || "en");

	// Function to change language and save it in local storage
	const changeLanguage = (language) => {
		selectedLanguage.value = language;
		localStorage.setItem("selectedLanguage", language);
	};
	const isPaymentComplete = ref(false);
	const razorpayCheckoutJS = ref(null);

	function goToHome() {
		localStorage.clear();
		router.push({ name: "Home" });
	}

	const get_consultation_charge = createResource({
		url: "/api/method/marley_frontend.api.get_practitioner_charge",
		method: "GET",
		params: {
			practitioner: practitioner,
			appointment: appointment
		 },
		onSuccess(data) {
			if (data) {
				consultation_charge.value = data.practitioner_charge;
				registration_fee.value = data.registration_fee;
				total_amount.value = data.total_amount;
				has_registration_fee = data.registration_fee ? true : false;
			}
		}
	});
	get_consultation_charge.fetch()

	onMounted(() => {
		razorpayCheckoutJS.value = document.createElement("script");
		razorpayCheckoutJS.value.setAttribute(
			"src",
			"https://checkout.razorpay.com/v1/checkout.js"
		);
		razorpayCheckoutJS.value.async = true;
		document.head.appendChild(razorpayCheckoutJS.value);
	});

	onBeforeUnmount(() => {
		razorpayCheckoutJS.value?.remove();
	});

	const createRazorpayOrder = createResource({
		url: "/api/method/marley_frontend.marley_frontend.doctype.wl_razorpay_settings.wl_razorpay_settings.create_razorpay_order",
		params: {
			practitioner: practitioner,
			appointment: appointment
		},
		onSuccess: data => processOrder(data),
	});

	const handlePaymentFailed = createResource({
		url: "marley_frontend.marley_frontend.doctype.razorpay_payment_record.razorpay_payment_record.handle_razorpay_payment_failed",
		onSuccess: () => {
			console.log("Payment Failed.");
		}
	});

	const PaymentSuccess = createResource({
		url: "marley_frontend.marley_frontend.doctype.razorpay_payment_record.razorpay_payment_record.handle_razorpay_payment_success",
		onSuccess: () => {
			console.log("Payment Success.");
		}
	});

	function processOrder(data) {
		const options = {
			key: data.key_id,
			order_id: data.order_id,
			name: data.display_name,
			image: data.image,
			prefill: { email: data.user },
			handler: handlePaymentSuccess,
			theme: { color: "#171717" }
		};

		const rzp = new Razorpay(options);

		// Opens the payment checkout frame
		rzp.open();

		// Attach failure handler
		rzp.on("payment.failed", handlePaymentFailure);
	}

	function handlePaymentFailure(response) {
		handlePaymentFailed.submit({ response });
	}

	function handlePaymentSuccess(response) {
		if (response) {
			PaymentSuccess.submit({ response });
		}
		isPaymentComplete.value = true;
		emit("success");
		router.push({
			name: "BookingSuccess",
			query: {
				from_checkin: from_checkin,
			}
		});		
	}
</script>
